mapper.select:
SELECT l.log_id, l.user_id, COALESCE(u.real_name, u.username) AS operatorName, l.module, l.action, l.target_class, l.target_method, l.request_params, l.duration_ms, l.status, l.error_msg, l.create_time FROM t_audit_log l LEFT JOIN t_user u ON u.user_id = l.user_id
AND l.module = #{module}
AND l.user_id = #{userId}
AND l.status = #{status}
ORDER BY l.create_time DESC

